    try {
      const res = await axios.put(`/income-streams/${id}`, formData);
      dispatch({
        type: 'UPDATE_INCOME_STREAM',
        payload: res.data.data,
      });
      return res.data.data;
    } catch (err) {
      // Only log out if it's an auth error (401)
      if (err.response?.status === 401) {
        dispatch({
          type: 'AUTH_ERROR',
          payload: err.response.data.message,
        });
      } else {
        dispatch({
          type: 'CLEAR_ERROR',
          payload: err.response?.data?.message || 'Failed to update income stream',
        });
      }
    }
  };

  // Delete income stream
  const deleteIncomeStream = async id => {
    try {
      await axios.delete(`/income-streams/${id}`);
      dispatch({
        type: 'DELETE_INCOME_STREAM',
        payload: id,
      });
    } catch (err) {
      // Only log out if it's an auth error (401)
      if (err.response?.status === 401) {
        dispatch({
          type: 'AUTH_ERROR',
          payload: err.response.data.message,
        });
      } else {
        dispatch({
          type: 'DELETE_INCOME_STREAM_ERROR',
          payload: err.response?.data?.message || 'Failed to delete income stream',
        });
      }
    }
  };

  // Get alerts
  const getAlerts = async () => {
    try {
      const res = await axios.get('/budgets/alerts');
      dispatch({
        type: 'GET_ALERTS',
        payload: res.data.data,
      });
    } catch (err) {
      // Only log out if it's an auth error (401)
      if (err.response?.status === 401) {
        dispatch({
          type: 'AUTH_ERROR',
          payload: err.response.data.message,
        });
      } else {
        dispatch({
          type: 'CLEAR_ERROR',
          payload: err.response?.data?.message || 'Failed to fetch alerts',
        });
      }
    }
  };

  // Set theme
  const setTheme = theme => {
    dispatch({
      type: 'SET_THEME',
      payload: theme,
    });
  };

  // Update user details
  

  // Initialize
  useEffect(() => {
    loadUser();
  }, []);

  return (
    <FinanceContext.Provider
      value={{
        ...state,
        register,
        login,
        logout,
        getTransactions,
        addTransaction,
        updateTransaction,
        deleteTransaction,
        getStats,
        getGoals,
        addGoal,
        updateGoal,
        updateGoalProgress,
        deleteGoal,
        getBudgets,
        addBudget,
        updateBudget,
        deleteBudget,
        getIncomeStreams,
        addIncomeStream,
        updateIncomeStream,
        deleteIncomeStream,
        getAlerts,
        setTheme,
        updateUserDetails,
        clearError,
      }}
    >
      {children}
    </FinanceContext.Provider>
  );
};
